				{ type = "quest", id = 831 },
			},
			text = [=[When the orders of {link:daelin-proudmoore}Daelin Proudmoore{/link} were found at {link:tiragarde-keep}Tiragarde Keep{/link}, they came at last to Vol'jin in {link:grommash-hold}Grommash Hold{/link}. He read them and was not surprised. He had long urged the Warchief not to trust the humans, and the admiral's plans proved him right. He did not gloat. He went at once to counsel {link:thrall}Thrall{/link}.]=],
		},
		{
			key = "the-hexmaster",
			title = "The Hexmaster",
			hint = "Bring down the witch doctor who holds the Echo Isles.",
			unlock = {
				{ type = "quest", id = 826 },
			},
			text = [=[Word of {link:zalazane}Zalazane{/link}'s fall came to {link:orgrimmar}Orgrimmar{/link} from {link:sen-jin-village}Sen'jin Village{/link}. For the chieftain of the {link:darkspear-trolls}Darkspear{/link}, it was a small comfort. The traitor's curse still lies upon the isles, and many of Vol'jin's people still wander there with empty minds. The day of the tribe's homecoming has not yet come.]=],
		},
	},
	mentions = {
		{
			text = "The Admiral's Orders",
			unlock = {
				{ type = "quest", id = 831 },
			},
		},
		{
			text = [=[{link:zalazane}Zalazane{/link}, slain at {link:master-gadrin}Master Gadrin{/link}'s request]=],
			unlock = {
				{ type = "quest", id = 826 },
