	hint = [=[Speak with the old warrior who counsels the Warchief in Grommash Hold.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Eitrigg is an old {link:orcs}orc{/link} warrior of the {link:blackrock-clan}Blackrock clan{/link} who serves {link:thrall}Thrall{/link} as counselor and overseer of the {link:horde}Horde{/link}'s recruits. He fought in the wars of the old Horde under Blackhand and Doomhammer. He came to hate the demon worshippers who led his people astray, and for a time he left the Horde altogether. He returned when he heard Thrall's vision of a Horde guided by shaman instead of demons.]=],
		},
		{
			title = "Significance",
			text = [=[Eitrigg is a bridge between the old {link:horde}Horde{/link} and the new. He knows the ways of the {link:blackrock-mountain}Blackrock{/link} better than any {link:orcs}orc{/link} in {link:orgrimmar}Orgrimmar{/link}, and he knows what it costs to leave them.]=],
		},
		{
			title = "Deeds",
			text = [=[• He served as a lieutenant of the {link:blackrock-mountain}Blackrock{/link} war chief in the days before the {link:dark-portal}Dark Portal{/link}, alongside {link:orgrim-doomhammer}Orgrim Doomhammer{/link}.
• He kept watch over the assassin {link:garona}Garona{/link} in the {link:second-war}Second War{/link}, and he let her go when she fled.
• He left the {link:horde}Horde{/link} and wandered north into the human lands, where he was taken prisoner and saved by the Warchief.
• He oversees the training of new recruits for {link:thrall}Thrall{/link}.]=],
