			hint = "Bring the head of Rend Blackhand to the Warchief.",
			unlock = {
				{ type = "quest", id = 4974 },
			},
			text = [=[When the head of Rend was laid before the Warchief, Eitrigg saw the last shadow of the clan he had once served broken. The {link:blackrock-mountain}Blackrock{/link} were thrown into chaos once more. For the old warrior, it was a debt settled.]=],
